"""Package reviewed research sources; never delete workspace files."""
import hashlib
import json
from pathlib import Path
import zipfile

ROOT = Path(__file__).resolve().parents[1]
AUDIT = ROOT / 'reports/submission_audit'
FOLDERS = {'src', 'config', 'data', 'experiments', 'tests', 'templates', 'static', 'reports'}
ROOT_FILES = {'main.py', 'app.py', 'README.md', 'FINAL_ACCEPTANCE.md', 'HANDOFF.md',
              'RESEARCH_ADDON_README.md', 'requirements.txt', 'requirements-lock.txt',
              'requirements-research.txt', 'pytest.ini', '.gitignore', 'DATA_NOTICE.md'}
REPORT_EXCLUDES = ('reports/final_acceptance/before_scientific/',
                   'reports/final_acceptance/scientific_updated/')


def classification(relative: Path) -> tuple[str, str]:
    name = relative.as_posix()
    parts = relative.parts
    if any(p in {'.venv', '.cache', '__pycache__', '.git', '.agents', '.codex', '.aws', 'dist'}
           or p.startswith('.pytest') for p in parts):
        return 'C', 'Environment/cache/temp/build output; retained on workstation'
    if name.startswith('reports/submission_audit/') and any(p in {'tmp', 'tmp_probe'} for p in parts):
        return 'C', 'Ephemeral pytest fixtures (may contain generated private test keys)'
    if name.startswith(REPORT_EXCLUDES) or relative.name == 'defense_slides.html':
        return 'C', 'Duplicate scientific report or presentation; canonical report retained'
    if relative.suffix in {'.pyc', '.pyo', '.zip'}:
        return 'C', 'Generated bytecode/archive'
    if len(parts) == 1 and relative.name not in ROOT_FILES:
        return 'D', 'Unselected root file; inspect before deleting'
    if len(parts) > 1 and parts[0] not in FOLDERS:
        return 'D', 'Outside reviewed submission folders; do not delete'
    if parts[0] == 'src' and relative.stem in {'aia_completion', 'revocation_checker', 'revocation_network',
            'ct_crypto', 'ct_inclusion', 'ct_registry', 'ct_signed_input', 'untrusted_tls'}:
        return 'B', 'Working optional security extension'
    if parts[0] in {'templates', 'static'} or name == 'app.py':
        return 'B', 'Localhost Flask demo'
    return 'A', 'Source/config/tests/reproducibility or original research evidence'


def build() -> None:
    AUDIT.mkdir(parents=True, exist_ok=True)
    rows = []
    # Prune very large environment/cache trees; classify each tree as one unit.
    for child in sorted(ROOT.iterdir()):
        if child.is_dir() and (child.name.startswith('.') or child.name in {'dist', '__pycache__'}):
            rows.append({'path': child.name + '/', 'group': 'C', 'included': False,
                         'reason': 'Local environment/cache/build tree, excluded recursively'})
            continue
        files = sorted(child.rglob('*')) if child.is_dir() else [child]
        for file in files:
            if not file.is_file():
                continue
            relative = file.relative_to(ROOT)
            if relative.as_posix() == 'reports/submission_audit/file_inventory.json':
                # The inventory is added separately; it cannot contain its own hash.
                continue
            group, reason = classification(relative)
            included = group in {'A', 'B'}
            row = {'path': relative.as_posix(), 'group': group, 'included': included, 'reason': reason}
            if included:
                data = file.read_bytes()
                if b'-----BEGIN PRIVATE KEY-----' in data or b'-----BEGIN RSA PRIVATE KEY-----' in data or b'-----BEGIN EC PRIVATE KEY-----' in data:
                    # Python test sources contain PEM marker literals; actual secret PEM is line anchored.
                    lines = data.splitlines()
                    if any(line.startswith(b'-----BEGIN ') and b'PRIVATE KEY-----' in line for line in lines):
                        raise ValueError(f'Private key in submission: {relative}')
                row.update(bytes=len(data), sha256=hashlib.sha256(data).hexdigest())
            rows.append(row)
    inventory = AUDIT / 'file_inventory.json'
    inventory.write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding='utf-8')
    target = ROOT / 'dist/DT007_submit.zip'
    target.parent.mkdir(exist_ok=True)
    selected = [r for r in rows if r['included'] and r['path'] != inventory.relative_to(ROOT).as_posix()]
    with zipfile.ZipFile(target, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for row in selected:
            archive.write(ROOT / row['path'], row['path'])
        archive.write(inventory, inventory.relative_to(ROOT).as_posix())
    with zipfile.ZipFile(target) as archive:
        assert archive.testzip() is None
        assert 'config/ct_log_list_pubkey.pem' in archive.namelist()
        for row in selected:
            assert hashlib.sha256(archive.read(row['path'])).hexdigest() == row['sha256']
    result = {'archive': str(target), 'bytes': target.stat().st_size,
              'sha256': hashlib.sha256(target.read_bytes()).hexdigest(), 'files': len(selected) + 1,
              'deleted_source_files': [], 'note': 'No previous ZIP existed in workspace at audit start'}
    (ROOT / 'dist/package_summary.json').write_text(json.dumps(result, indent=2), encoding='utf-8')
    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    build()
